    "code": "class Solution {\n  private int[] rows = new int[9], cols = new int[9], boxes = new int[9];   // one bit per digit\n  public char[][] solveSudoku(char[][] board) {\n    for (int r = 0; r < 9; r++)\n      for (int c = 0; c < 9; c++)\n        if (board[r][c] != '.') flip(r, c, board[r][c] - '1');\n    solve(board, 0);\n    return board;\n  }\n  private void flip(int r, int c, int d) {\n    int bit = 1 << d;\n    rows[r] ^= bit; cols[c] ^= bit; boxes[r / 3 * 3 + c / 3] ^= bit;\n  }\n  private boolean solve(char[][] board, int pos) {\n    while (pos < 81 && board[pos / 9][pos % 9] != '.') pos++;   // next empty cell\n    if (pos == 81) return true;\n    int r = pos / 9, c = pos % 9;\n    int used = rows[r] | cols[c] | boxes[r / 3 * 3 + c / 3];\n    for (int d = 0; d < 9; d++) {\n      if ((used & (1 << d)) != 0) continue;                     // digit already used\n      board[r][c] = (char) ('1' + d);\n      flip(r, c, d);\n      if (solve(board, pos + 1)) return true;\n      flip(r, c, d);\n      board[r][c] = '.';\n    }\n    return false;\n  }\n}"
